urlset:
{%- for file in pages %}
  {%- if not file.page.is_link and file.page.url not in jd_single %}
    {%- set url = file.page.canonical_url if file.page.canonical_url else (config.site_url ~ file.page.url) %}

    {{ url | e }}
    {%- if file.page.meta and file.page.meta.document_dates and file.page.meta.document_dates.dates.updated %}
    {{ file.page.meta.document_dates.dates.updated | jd_date('iso') }}
    {%- elif file.page.update_date %}
    {{ file.page.update_date }}
    {%- endif %}

  {%- endif %}
{%- endfor %}
